function renderProjectLifecycle(){const project=selectedProject(),enabled=state.capabilities.includes("local_project_states_v1")&&Boolean(project),value=project?projectState(project.id):null,command=project?projectStateCommands.get(project.id):null,toggle=$("project-state-toggle"),review=$("project-state-review"),feedback=$("project-state-feedback");protectWorkControlFocus(toggle,!enabled||state.readOnly||Boolean(command));toggle.hidden=!enabled;toggle.disabled=state.readOnly||!value||Boolean(command);toggle.textContent=value?.archived?"Khôi phục dự án":"Lưu trữ dự án";toggle.setAttribute("aria-label",toggle.textContent+" · "+(project?.name??"Dự án"));protectWorkControlFocus(review,!command||Boolean(command.pending));review.hidden=!command;review.disabled=Boolean(command?.pending);if(feedback.contains(document.activeElement))$("work-close").focus({preventScroll:true});feedback.replaceChildren();feedback.hidden=!command;if(command){feedback.append(node("p","form-note",command.message));const retry=node("button","text-button","Thử lại lệnh gốc");retry.type="button";retry.hidden=Boolean(command.rejected);retry.disabled=state.readOnly||command.pending;retry.addEventListener("click",()=>runProjectLifecycle(command));feedback.append(retry)}if(value?.archived){$("project-scope-note").textContent="Đã lưu trữ · Quyền dự án v"+project.revision+" vẫn giữ nguyên. Xem lịch sử và tải tệp theo quyền hiện có; khôi phục để nhận yêu cầu mới.";if($("upload-dialog").open&&uploadTarget?.projectId===project.id&&!uploadReselect){disableUploadSave(true);$("upload-status").textContent="Dự án đã lưu trữ. Tệp chưa gửi vẫn giữ; khôi phục và mở lại thao tác thêm tệp."}}}
async function runProjectLifecycle(command){if(state.readOnly||command.pending||command.rejected||!state.capabilities.includes("local_project_states_v1"))return;command.pending=true;command.message="Đang lưu trạng thái cho dự án gốc; việc đã nhận tiếp tục.";render();try{const result=await request("/v1/projects/"+encodeURIComponent(command.id)+"/state",command.body);if(result.projectState?.projectId!==command.id||!acceptProjectState(result.projectState))await sync();projectStateCommands.delete(command.id)}catch(error){const code=Number(error.message);command.rejected=[400,404,409].includes(code);command.message=command.rejected?"Dự án đã đổi bản lưu. Đọc lại trước khi chọn trạng thái mới.":"Chưa nhận xác nhận. Thử lại giữ đúng dự án, trạng thái, phiên bản và mã lệnh gốc.";if(code===409)try{await sync()}catch{}}finally{command.pending=false;render()}}
$("project-state-toggle").addEventListener("click",async()=>{const project=selectedProject(),value=project?projectState(project.id):null;if(!value||$("project-state-toggle").disabled)return;const command={id:project.id,body:{action:value.archived?"restore":"archive",expectedRevision:value.revision,clientNonce:crypto.randomUUID()}};projectStateCommands.set(project.id,command);await runProjectLifecycle(command)});
